sysevent_register.script:
// Event Script: Trade Book Record Inserted
// Purpose: Handle additional processing when new trade records are created

(function process(/*GlideRecord*/ gr, /*GlideRecord*/ previous) {

    try {
        // Get event parameters
        var stockName = event.parm1 || 'Unknown';
        var tradeNumber = event.parm2 || 'N/A';

        // Log the event
        gs.info('Trade Book Event: Processing new trade record for ' + stockName + ' (Trade #' + tradeNumber + ')');

        // Additional processing can be added here:
        // - Send notifications to specific user groups
        // - Update related records
        // - Trigger workflows
        // - Integration with external systems

        // Example: Send notification to trade managers group
        var notification = new GlideRecord('sys_email');
        notification.initialize();
        notification.type = 'send-ready';
        notification.recipients = 'trade.managers@company.com';
        notification.subject = 'Trade Alert: New Position Opened - ' + stockName;
        notification.body = 'A new trading position has been opened.\n\n' +
                           'Trade Number: ' + tradeNumber + '\n' +
                           'Stock: ' + stockName + '\n\n' +
                           'Please review the trade in the Trade Book application.';
        notification.insert();

    } catch (error) {
        gs.error('Error in Trade Book event processing: ' + error.message);
    }

})(event.parm1, event.parm2);
